CREATE TABLE ezurlalias_ml (parent INT DEFAULT 0 NOT NULL, text_md5 VARCHAR(32) DEFAULT '' NOT NULL, action LONGTEXT NOT NULL, action_type VARCHAR(32) DEFAULT '' NOT NULL, alias_redirects INT DEFAULT 1 NOT NULL, id INT DEFAULT 0 NOT NULL, is_alias INT DEFAULT 0 NOT NULL, is_original INT DEFAULT 0 NOT NULL, lang_mask BIGINT DEFAULT 0 NOT NULL, link INT DEFAULT 0 NOT NULL, text LONGTEXT NOT NULL, INDEX ezurlalias_ml_actt_org_al (action_type, is_original, is_alias), INDEX ezurlalias_ml_text_lang (text(32), lang_mask, parent), INDEX ezurlalias_ml_par_act_id_lnk (action(32), id, link, parent), INDEX ezurlalias_ml_par_lnk_txt (parent, text(32), link), INDEX ezurlalias_ml_act_org (action(32), is_original), INDEX ezurlalias_ml_text (text(32), id, link), INDEX ezurlalias_ml_link (link), INDEX ezurlalias_ml_id (id), PRIMARY KEY(parent, text_md5)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
